1	package jobs
2	
3	import (
4		"context"
5		"time"
6	)
7	
8	// MaxFinishedRuns is how many settled runs the registry keeps. Runs live for
9	// the session (D8) — they are not written anywhere and do not survive a
10	// restart — but a session that scans all day would otherwise grow a list
11	// nobody scrolls to the end of.
12	//
13	// Twenty is the count at which the oldest entry has stopped being useful: the
14	// question a jobs view answers about a finished run is "did that one work?",
15	// and it is asked about the last few.
16	const MaxFinishedRuns = 20
17	
18	// Registry is the one place that knows what is running.
19	//
20	// It is **not safe for concurrent use, deliberately**. It is owned by the
21	// router and mutated from Update alone, which is where Rule 110 puts every
22	// write to application state; a mutex here would say a Cmd may touch it, and
23	// that is exactly the thing that must stay untrue. What a Cmd does is return a
24	// message, and Update turns that into a transition.
25	type Registry struct {
26		runs   []*Run
27		nextID JobID
28		// clock is time.Now in production and a fixed hand in tests, so a run's
29		// StartedAt is an assertion rather than a tolerance.
30		clock func() time.Time
31	}
32	
33	// New returns an empty registry.
34	func New() *Registry {
35		return &Registry{clock: time.Now}
36	}
37	
38	// SetClock replaces the registry's idea of now. It exists for tests.
39	func (r *Registry) SetClock(clock func() time.Time) { r.clock = clock }
40	
41	// Start admits a run, stamps it and returns its identifier.
42	//
43	// The run arrives with every item queued and is registered from Update, at the
44	// moment the commands are dispatched — never from inside one (D10). Every
45	// launch site knows its full list of targets at that point, which is what makes
46	// "8 waiting" sayable at all.
47	func (r *Registry) Start(run Run) JobID {
48		r.nextID++
49		run.ID = r.nextID
50		if run.StartedAt.IsZero() {
51			run.StartedAt = r.now()
52		}
53		if run.Finished() {
54			run.EndedAt = run.StartedAt
55		}
56		r.runs = append(r.runs, &run)
57		r.prune()
58		return run.ID
59	}
60	
61	// Advance moves one item of a run to a new state.
62	//
63	// A transition addressed to a run or a target the registry does not hold is
64	// reported rather than ignored: it means a launch site emitted a message for
65	// work it never registered, and the visible symptom would be a row that spins
66	// for the life of the view — the failure this package exists to remove.
67	func (r *Registry) Advance(id JobID, target string, state ItemState, detail string) bool {
68		return r.advance(id, target, state, detail, nil)
69	}
70	
71	// advance is Advance with the cancel function a starting transition carries.
72	//
73	// It arrives here and not through a call of its own because the two are one
74	// event: the context is created inside the Cmd, so the function reaches Update
75	// in the very message that says the item started. Two calls would leave a
76	// window where the item is running and cannot be stopped.
77	func (r *Registry) advance(id JobID, target string, state ItemState, detail string, cancel context.CancelFunc) bool {
78		run := r.run(id)
79		if run == nil {
80			return false
81		}
82		for i := range run.Items {
83			if run.Items[i].Target != target {
84				continue
85			}
86			run.Items[i].State = state
87			run.Items[i].Detail = detail
88			switch {
89			case state.Terminal():
90				run.Items[i].cancel = nil
91			case cancel != nil:
92				run.Items[i].cancel = cancel
93			}
94			r.settle(run)
95			return true
96		}
97		return false
98	}
99	
100	// Transition is what a progress message says about one target.
101	//
102	// It exists so the router can apply a message without knowing the vocabulary of
103	// the view that sent it. A sync that was refused because the tree is dirty is a
104	// skip with a reason; only the workspaces package knows that, and it says so by
105	// answering this — see Reporter.
106	type Transition struct {
107		Kind   Kind
108		Target string
109		State  ItemState
110		Detail string
111	
112		// Cancel stops the work this transition reports as started, and is nil for
113		// every other transition and for the kinds that cannot be cut (D7).
114		//
115		// It travels on the transition rather than through a call of its own
116		// because the two are one event: the context is created inside the Cmd, so
117		// the function reaches Update in the message that says the item started.
118		Cancel context.CancelFunc
119	
120		// Discover says the target has no row yet and belongs to the open run of
121		// this kind (D3). Only a kind whose targets arrive progressively sets it —
122		// the clone, whose walk is what finds them — and for every other kind it
123		// stays false because the full list was known at launch.
124		Discover bool
125	}
126	
127	// Reporter is implemented by a message that reports on registered work.
128	//
129	// The alternative was a switch in the router mapping every view's outcome
130	// vocabulary onto item states, which puts each view's semantics in a file that
131	// belongs to none of them, and grows by one branch per view.
132	type Reporter interface {
133		Transition() Transition
134	}
135	
136	// Sealer is implemented by the message that says a kind's open run has found
137	// everything it is going to (D3).
138	//
139	// It is a second interface rather than a field on Transition because sealing
140	// names no target: the message that carries it is the closed event channel, and
141	// there is nothing for it to be about.
142	type Sealer interface {
143		Seal() Kind
144	}
145	
146	// Apply routes a transition to the run it belongs to. It reports whether one
147	// was found, which is how the router knows there is something new to broadcast.
148	func (r *Registry) Apply(t Transition) bool {
149		if t.Discover {
150			return r.Discover(t.Kind, t.Target, t.State, t.Detail)
151		}
152		id, ok := r.FindItem(t.Kind, t.Target)
153		if !ok {
154			return false
155		}
156		return r.advance(id, t.Target, t.State, t.Detail, t.Cancel)
157	}
158	
159	// Discover adds a target to the open run of a kind (D3).
160	//
161	// A target already there is advanced instead of duplicated: the walk reports a
162	// group it could not list as a target of its own, and that path may also have
163	// been found as a repository. One row, whichever arrives first.
164	func (r *Registry) Discover(kind Kind, target string, state ItemState, detail string) bool {
165		run := r.openRun(kind)
166		if run == nil {
167			return false
168		}
169		for i := range run.Items {
170			if run.Items[i].Target == target {
171				run.Items[i].State = state
172				run.Items[i].Detail = detail
173				r.settle(run)
174				return true
175			}
176		}
177		run.Items = append(run.Items, Item{Target: target, State: state, Detail: detail})
178		r.settle(run)
179		return true
180	}
181	
182	// Seal says the open run of a kind has discovered everything it is going to.
183	//
184	// Until it is called the run is unsettled whatever its items say, which is the
185	// point: a walk that has found three repositories and cloned all three is not
186	// done. Sealing is what lets the run finish, stamp EndedAt and let the spinner
187	// chain die.
188	func (r *Registry) Seal(kind Kind) bool {
189		run := r.openRun(kind)
190		if run == nil {
191			return false
192		}
193		run.open = false
194		r.settle(run)
195		return true
196	}
197	
198	// CancelOpen stops the open run of a kind.
199	//
200	// It exists because a progressive run is the one case a view can name without
201	// a target: there is exactly one open run per kind at a time — the screen that
202	// owns it is exclusive while it goes — so "the clone I am looking at" resolves
203	// without the view holding a JobID, which is the thing D1 keeps out of views.
204	func (r *Registry) CancelOpen(kind Kind) bool {
205		run := r.openRun(kind)
206		if run == nil {
207			return false
208		}
209		return r.Cancel(run.ID)
210	}
211	
212	// openRun is the run of a kind that is still discovering, if there is one.
213	//
214	// At most one can exist: an open run belongs to a screen that owns the display
215	// while it goes, so a second could only be started by leaving that screen —
216	// which closes the first. The newest wins if that invariant is ever broken, so
217	// the answer is the run a user is looking at rather than one they have left.
218	func (r *Registry) openRun(kind Kind) *Run {
219		for i := len(r.runs) - 1; i >= 0; i-- {
220			if r.runs[i].Kind == kind && r.runs[i].open {
221				return r.runs[i]
222			}
223		}
224		return nil
225	}
226	
227	// FindItem names the run a transition belongs to.
228	//
229	// The launch sites do not carry a JobID in their messages, and deliberately:
230	// a view would have to hold one, which means holding registry state — the thing
231	// D1 keeps out of the views — and it would have to hold it before the registry
232	// had allocated it. The router looks the run up instead, from what the message
233	// already says: the kind is decided by which message arrived, and the target is
234	// in it.
235	//
236	// The oldest unsettled run wins. Two live runs of one kind cannot hold the same
237	// target — that is what the busy() guards prevent, and they are answered from
238	// this registry now, so the exclusion is enforced rather than hoped for.
239	func (r *Registry) FindItem(kind Kind, target string) (JobID, bool) {
240		for _, run := range r.runs {
241			if run.Kind != kind || run.Finished() {
242				continue
243			}
244			for i := range run.Items {
245				if run.Items[i].Target == target && !run.Items[i].State.Terminal() {
246					return run.ID, true
247				}
248			}
249		}
250		return 0, false
251	}
252	
253	// AttachRun stores the cancel function that stops the run's queue, as opposed
254	// to one item's work.
255	func (r *Registry) AttachRun(id JobID, cancel context.CancelFunc) {
256		if run := r.run(id); run != nil {
257			run.cancel = cancel
258		}
259	}
260	
261	// Cancel asks a run to stop.
262	//
263	// What that means differs by kind, and the difference is not cosmetic (D7):
264	// the queue always stops, so nothing further starts, but work already in flight
265	// is only interrupted where interrupting it leaves nothing behind. A `git
266	// clone` is never cut — a cancelled one leaves half a repository on disk — and
267	// a delete is not cancellable at all, which is a guard the view carries
268	// (Kind.Cancellable).
269	//
270	// Queued items are marked skipped straight away: they will not run, and leaving
271	// them queued would keep the run reading as running forever.
272	func (r *Registry) Cancel(id JobID) bool {
273		run := r.run(id)
274		if run == nil || run.Finished() {
275			return false
276		}
277	
278		run.cancelled = true
279		// A cancelled walk finds nothing more, so the run is sealed here: leaving
280		// it open would keep it unsettled for the life of the session, spinner
281		// chain and all, with nothing left that could ever close it.
282		run.open = false
283		if run.cancel != nil {
284			run.cancel()
285			run.cancel = nil
286		}
287	
288		for i := range run.Items {
289			switch run.Items[i].State {
290			case ItemQueued:
291				run.Items[i].State = ItemSkipped
292				run.Items[i].Detail = "cancelled"
293			case ItemRunning:
294				// Asked to stop, not declared stopped: the item reports its own
295				// outcome when it gets there. Claiming it settled here would race
296				// the message that says how it actually ended.
297				if run.Items[i].cancel != nil {
298					run.Items[i].cancel()
299					run.Items[i].cancel = nil
300				}
301			}
302		}
303	
304		r.settle(run)
305		return true
306	}
307	
308	// CancelItem stops one target of a run, leaving the rest going.
309	//
310	// It is the narrow half of D7: the run-level Cancel stops the queue whatever
311	// the kind, and this cuts a single piece of work — which is only offered where
312	// cutting leaves nothing behind. The caller decides that (Run.ItemStoppable);
313	// this refuses only what it cannot do.
314	//
315	// A queued target is skipped outright, because it will not run. A running one
316	// is *asked* to stop and left running: it reports its own outcome when it gets
317	// there, and claiming it settled here would race the message that says how it
318	// actually ended — the same reason Cancel gives.
319	func (r *Registry) CancelItem(id JobID, target string) bool {
320		run := r.run(id)
321		if run == nil || run.Finished() {
322			return false
323		}
324		for i := range run.Items {
325			if run.Items[i].Target != target || run.Items[i].State.Terminal() {
326				continue
327			}
328			if run.Items[i].State == ItemQueued {
329				run.Items[i].State = ItemSkipped
330				run.Items[i].Detail = "cancelled"
331			} else if run.Items[i].cancel != nil {
332				run.Items[i].cancel()
333				run.Items[i].cancel = nil
334			}
335			r.settle(run)
336			return true
337		}
338		return false
339	}
340	
341	// Snapshot returns a copy of every run, oldest first.
342	//
343	// It is what JobsChangedMsg carries, and copying is what makes the broadcast
344	// honest: a view holds data, not a window onto state someone else is writing.
345	// The cancel functions are cleared on the way out — a snapshot cannot stop a
346	// job, which has to go through Cancel on the registry the router owns.
347	func (r *Registry) Snapshot() []Run {
348		out := make([]Run, 0, len(r.runs))
349		for _, run := range r.runs {
350			copied := *run
351			copied.cancel = nil
352			copied.Items = make([]Item, len(run.Items))
353			copy(copied.Items, run.Items)
354			for i := range copied.Items {
355				copied.Items[i].cancel = nil
356			}
357			out = append(out, copied)
358		}
359		return out
360	}
361	
362	// Running counts the runs that have not settled. It is what decides whether the
363	// router keeps its spinner chain alive, and what the degraded footer line
364	// counts (D9).
365	func (r *Registry) Running() int {
366		n := 0
367		for _, run := range r.runs {
368			if !run.Finished() {
369				n++
370			}
371		}
372		return n
373	}
374	
375	// Len returns how many runs the registry holds, settled ones included.
376	func (r *Registry) Len() int { return len(r.runs) }
377	
378	// run finds a run by identifier.
379	func (r *Registry) run(id JobID) *Run {
380		for _, run := range r.runs {
381			if run.ID == id {
382				return run
383			}
384		}
385		return nil
386	}
387	
388	// settle stamps EndedAt the first time a run is found finished, and drops the
389	// oldest settled runs once there are more than the cap allows.
390	func (r *Registry) settle(run *Run) {
391		if run.Finished() && run.EndedAt.IsZero() {
392			run.EndedAt = r.now()
393		}
394		r.prune()
395	}
396	
397	// prune keeps at most MaxFinishedRuns settled runs, dropping the oldest first.
398	// A run still going is never dropped, whatever its age: the registry losing
399	// track of live work is the one failure that would leave a view spinning.
400	func (r *Registry) prune() {
401		finished := 0
402		for _, run := range r.runs {
403			if run.Finished() {
404				finished++
405			}
406		}
407		excess := finished - MaxFinishedRuns
408		if excess <= 0 {
409			return
410		}
411	
412		kept := make([]*Run, 0, len(r.runs)-excess)
413		for _, run := range r.runs {
414			if excess > 0 && run.Finished() {
415				excess--
416				continue
417			}
418			kept = append(kept, run)
419		}
420		r.runs = kept
421	}
422	
423	func (r *Registry) now() time.Time {
424		if r.clock == nil {
425			return time.Now()
426		}
427		return r.clock()
428	}
429

