411		if got[0].Target != "/w/t2" {
412			t.Errorf("oldest = %q, want /w/t2 (t1 should have been evicted)", got[0].Target)
413		}
414		if has(r, keyOf(KindScan, "/w/t1", "ctx")) {
415			t.Error("the oldest failure was kept")
416		}
417		if got[len(got)-1].Target != fmt.Sprintf("/w/t%d", MaxFailures+1) {
418			t.Errorf("newest = %q", got[len(got)-1].Target)
419		}
420		if r.Len() > MaxFinishedRuns {
421			t.Errorf("the registry holds %d runs: the cap must not depend on them", r.Len())
422		}
423	}
