425	func TestARefreshedFailureIsTheLastToBeEvicted(t *testing.T) {
426		r := at(noon)
427		for i := 1; i <= MaxFailures; i++ {
428			failItem(r, KindScan, "ctx", fmt.Sprintf("/w/t%d", i), "x")
429		}
430		failItem(r, KindScan, "ctx", "/w/t1", "again") // refresh #1
431		failItem(r, KindScan, "ctx", fmt.Sprintf("/w/t%d", MaxFailures+1), "x")
432	
433		if !has(r, keyOf(KindScan, "/w/t1", "ctx")) {
434			t.Error("the refreshed failure was evicted")
435		}
